(function () {
  'use strict';
  const M=window.CareFlowModel;
  const $=selector=>document.querySelector(selector);
  const h=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icons={
    home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',
    route:'<circle cx="6" cy="5" r="2"/><circle cx="18" cy="19" r="2"/><path d="M8 5h8a4 4 0 0 1 0 8H8a4 4 0 0 0 0 8h4"/>',
    buildings:'<path d="M4 21V8h7v13M11 21V3h9v18M2 21h20M7 11v1m0 4v1m7-10h3m-3 4h3m-3 4h3"/>',
    bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M9 21h6"/>',
    chart:'<path d="M4 3v18h17M8 17v-5m5 5V8m5 9V5"/>',
    settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="currentColor" stroke="none"/><circle cx="15" cy="17" r="3" fill="currentColor" stroke="none"/>',
    sparkle:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5zM20 2v4m-2-2h4"/>',
    help:'<circle cx="12" cy="12" r="9"/><path d="M9.3 9a2.8 2.8 0 0 1 5.4 1c0 2-2.7 2-2.7 4m0 3h.01"/>',
    'arrow-up-right':'<path d="M6 18 18 6M6 6h12v12"/>',
    'arrow-right':'<path d="M4 12h16m-6-6 6 6-6 6"/>',
    'chevron-down':'<path d="m6 9 6 6 6-6"/>',
    'chevron-right':'<path d="m9 5 7 7-7 7"/>',
    pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',
    menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
    sliders:'<path d="M6 3v18M18 3v18M12 3v18M3 8h6M9 16h6m0-7h6"/>',
    clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
    calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-13 5h2m4 0h2"/>',
    stethoscope:'<path d="M6 3v3m8-3v3M4 4v7a6 6 0 0 0 12 0V4M10 17v1a4 4 0 0 0 8 0v-3"/><circle cx="18" cy="12" r="3"/>',
    scan:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m8 0h5v-5M8 8l8 8m0-8-8 8M3 12h18"/>',
    pill:'<path d="M20 4a5 5 0 0 1 0 7l-9 9a5 5 0 0 1-7-7l9-9a5 5 0 0 1 7 0ZM8 9l7 7"/>',
    heart:'<path d="M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-3 3-1 7 1 9l7 7 7-7c2-2 4-6 1-9Z"/><path d="M4 12h4l2-4 3 8 2-4h5"/>',
    refresh:'<path d="M20 8a8 8 0 0 0-14-3L3 8m0-5v5h5M4 16a8 8 0 0 0 14 3l3-3m0 5v-5h-5"/>',
    check:'<path d="m5 12 4 4L19 6"/>',
    shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6"/>',
    money:'<path d="M7 3h10M7 7h10M8 3a5 5 0 0 1 0 10H7l9 8"/>',
    car:'<path d="m5 6-2 7v6h3v-3h12v3h3v-6l-2-7zM3 12h18M6 15h2m8 0h2"/>',
    info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',
    list:'<path d="M9 6h11M9 12h11M9 18h11M4 6h.01M4 12h.01M4 18h.01"/>',
    map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2zM9 3v16m6-14v16"/>',
    alert:'<path d="m12 3 10 18H2zM12 9v5m0 3h.01"/>',
    save:'<path d="M5 3h12l4 4v14H3V3zm2 0v6h10V3M7 21v-8h10v8"/>',
    print:'<path d="M6 8V3h12v5M6 17H3V9h18v8h-3M6 14h12v7H6zM17 11h1"/>',
    user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',
    close:'<path d="m6 6 12 12M18 6 6 18"/>',
    external:'<path d="M14 3h7v7m-9 2 9-9M9 3H3v18h18v-6"/>',
    edit:'<path d="m15 4 5 5M4 15 15 4a3.5 3.5 0 0 1 5 5L9 20l-6 1z"/>',
    layers:'<path d="m12 3 10 5-10 5L2 8zm-10 9 10 5 10-5M2 16l10 5 10-5"/>',
    users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 5v2"/>'
  };
  const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.heart}</svg>`;
  const money=n=>'₹'+Number(n).toLocaleString('en-IN');
  const defaultRequest=()=>M.parseRequest('I need an orthopedic consultation and an X-ray today.','consultation','Today','balanced');
  const initialUpdates=()=>[{id:1,title:'Welcome to your CareFlow workspace',text:'Explore a complete visit, compare your options, and try a service-change scenario with the demo controls.',type:'info',time:'Demo day · 12:30 PM',read:false}];
  const state={facilities:M.facilities(),request:defaultRequest(),plan:null,profile:{name:'Guest patient',location:'New Delhi',priority:'balanced',reducedMotion:false},updates:initialUpdates(),history:[],viewMode:'list',mapId:'C',mapZoom:1,filter:'all',sort:'recommended',hospitalId:'C',analysisStep:0,analysisTimer:null,screen:'home'};
  try {
    const saved=JSON.parse(localStorage.getItem('careflow-ui-v1')||'null');
    if(saved?.version===1){
      const profile=saved.profile||{};
      if(typeof profile.name==='string'&&profile.name.trim())state.profile.name=profile.name.trim().slice(0,60);
      if(typeof profile.location==='string'&&profile.location.trim())state.profile.location=profile.location.trim().slice(0,80);
      if(['balanced','wait','cost'].includes(profile.priority))state.profile.priority=profile.priority;
      state.profile.reducedMotion=profile.reducedMotion===true;
      state.request.priority=state.profile.priority;
      if(Array.isArray(saved.facilities))state.facilities.forEach(f=>{
        const previous=saved.facilities.find(item=>item?.id===f.id);
        if(!previous)return;
        if(typeof previous.doctor==='boolean')f.doctor=previous.doctor;
        if(Number.isFinite(previous.wait)&&previous.wait>=5&&previous.wait<=120)f.wait=previous.wait;
        ['xray','lab','pharmacy'].forEach(key=>{if(typeof previous.services?.[key]==='boolean')f.services[key]=previous.services[key];});
      });
      const previousPlan=saved.plan;
      const previousRequest=previousPlan?.request;
      if(previousPlan&&state.facilities.some(f=>f.id===previousPlan.facilityId)&&previousRequest&&Array.isArray(previousRequest.services)&&previousRequest.services.length&&previousRequest.services.every(s=>Object.hasOwn(M.serviceLabels,s))&&typeof previousRequest.specialty==='string'){
        const restoredRequest={...defaultRequest(),...previousRequest};
        const facility=state.facilities.find(f=>f.id===previousPlan.facilityId);
        const lastStep=M.timeline(facility,restoredRequest).length-1;
        const step=Number.isInteger(previousPlan.step)?Math.max(-1,Math.min(lastStep,previousPlan.step)):-1;
        state.plan={facilityId:facility.id,request:restoredRequest,step,status:step===lastStep?'complete':!M.evaluate(facility,restoredRequest).eligible?'needs-review':step<0?'ready':'in-progress'};
        state.request=M.clone(restoredRequest);
      }
      if(Array.isArray(saved.history))state.history=saved.history.filter(item=>item&&typeof item.facility==='string'&&typeof item.services==='string').slice(-50);
    }
  }
  catch{/* Local storage is optional, including when opened directly from disk. */}
  const persist=()=>{try{localStorage.setItem('careflow-ui-v1',JSON.stringify({version:1,profile:state.profile,plan:state.plan,facilities:state.facilities,history:state.history}));return true;}catch{return false;}};
  const ranked=(request=state.request)=>M.rank(state.facilities,request);
  const best=()=>ranked().find(f=>f.eligible);
  const facilityById=id=>state.facilities.find(f=>f.id===id);
  const evaluated=id=>M.evaluate(facilityById(id),state.request);
  const requestLabel=request=>request.services.map(s=>s==='consultation'?request.specialty:s==='followup'?request.specialty+' follow-up':M.serviceLabels[s]).join(' + ');
  const tags=request=>request.services.map(s=>`<span class="service-tag">${icon(s==='xray'||s==='lab'?'scan':s==='pharmacy'?'pill':'stethoscope')}${h(s==='consultation'&&request.specialty!=='General medicine'?request.specialty:M.serviceLabels[s])}</span>`).join('');
  function statusBadge(f){return f.eligible?'<span class="badge positive"><i></i>All services available</span>':'<span class="badge warning">'+icon('alert')+h(f.missing.includes('doctor')?'Doctor unavailable':f.missing.includes('specialty')?'Specialty unavailable':'Required service unavailable')+'</span>';}
  function completionRing(value,small=false){return `<div class="completion-ring ${small?'small':''}" role="img" aria-label="${value} percent simulated completion estimate"><svg viewBox="0 0 100 100" aria-hidden="true"><circle class="ring-track" cx="50" cy="50" r="42"/><circle class="ring-fill" cx="50" cy="50" r="42" stroke-dasharray="${value*2.639} 264"/></svg><div><strong>${value}<span>%</span></strong>${small?'':'<small>DEMO ESTIMATE</small>'}</div></div>`;}
  function heading(eyebrow,title,description,extra=''){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1>${description?`<p class="page-description">${description}</p>`:''}</div>${extra}</div>`;}
  function footerNote(){return `<div class="estimate-note">${icon('info')}<span>All facilities, prices and completion estimates in this prototype are fictional. Estimates demonstrate the interface and are not validated predictions.</span></div>`;}
  function requestSummary(){return `<div class="request-summary"><span class="round-icon pale">${icon('stethoscope')}</span><div><strong>${h(requestLabel(state.request))}</strong><span>${h(state.profile.location)} · ${h(state.request.day)} (demo) · ${state.request.priority==='cost'?'Lower cost':state.request.priority==='wait'?'Less waiting':'Balanced visit'}</span></div><button class="text-button" data-action="edit-request">Edit request ${icon('edit')}</button></div>`;}
  function planPreview(f,mode='preview'){
    if(!f)return `<section class="card empty-card">${icon('buildings')}<h2>No complete visit found</h2><p>Try another care request or restore the demo availability.</p><button class="button primary" data-action="reset-demo">Reset demo</button></section>`;
    return `<section class="best-plan-card"><div class="best-plan-top"><span>${icon('sparkle')} ${mode==='preview'?'EXAMPLE VISIT PLAN':'YOUR RECOMMENDED PLAN'}</span><span class="light-badge">${mode==='preview'?'Preview':'Best fit'}</span></div><div class="facility-intro"><span class="facility-letter">${f.id}</span><div><h2>${h(f.name)}</h2><p>${h(f.area)} · ${f.travel} min from your location</p></div></div><div class="plan-highlight"><div><span class="caption">SUGGESTED ARRIVAL</span><strong>1:20 <span>PM</span></strong><span>${h(state.request.day)} · demo schedule</span></div>${completionRing(f.completion)}</div><div class="plan-stats"><div>${icon('clock')}<strong>${f.wait} min</strong><span>Expected wait</span></div><div>${icon('car')}<strong>${f.travel} min</strong><span>Travel time</span></div><div>${icon('money')}<strong>${money(f.cost)}</strong><span>Estimated cost</span></div></div><div class="plan-services">${tags(state.request)}</div><div class="plan-status">${icon('check')} Required services available <span>Simulated</span></div><button class="button plan-cta" data-action="${mode==='preview'?'preview-request':'choose-plan'}" data-id="${f.id}">${mode==='preview'?'Preview this visit':'Start visit plan'} ${icon('arrow-right')}</button><p class="plan-disclaimer">Completion is a simulated planning estimate, not a guarantee.</p></section>`;
  }
  function home(){
    return `${heading('YOUR CARE, CONNECTED','Where should I go,<br>and <em>when should I arrive?</em>','A complete plan for your visit, with less guesswork along the way.',`<div class="date-card">${icon('calendar')}<div><strong>A little planning. A calmer day.</strong><span>Let’s make every part of your visit count.</span></div></div>`)}
    <div class="home-grid"><section class="card request-card"><div class="section-heading"><span class="round-icon pale">${icon('heart')}</span><div><h2>Let’s plan your visit</h2><p>Tell us what you need care for.</p></div><span class="step-label">STEP 01</span></div>
    <form id="care-form"><label class="field-label">I’m looking for</label><div class="care-options" role="group" aria-label="Care category">${[['consultation','stethoscope','Consultation'],['test','scan','Test / X-ray'],['pharmacy','pill','Pharmacy'],['followup','refresh','Follow-up'],['urgent','heart','Urgent care']].map(([id,ic,label])=>`<button type="button" class="care-option ${state.request.category===id?'selected':''}" data-action="category" data-category="${id}" aria-pressed="${state.request.category===id}">${icon(ic)}${label}</button>`).join('')}</div>
    <div class="textarea-label"><label for="care-need" class="field-label">What do you need for this visit?</label><button type="button" class="text-button" data-action="fill-example">Try an example ${icon('sparkle')}</button></div><textarea id="care-need" name="need" rows="4" maxlength="500" required aria-describedby="request-help" placeholder="For example: an orthopedic consultation and an X-ray today">${h(state.request.text)}</textarea><p id="request-help" class="field-help">Enter a requested consultation or service. This demo does not diagnose symptoms.</p>
    <div class="form-row"><div class="field"><label for="care-location">Your location</label><div class="input-icon">${icon('pin')}<input id="care-location" name="location" value="${h(state.profile.location)}" maxlength="80" required autocomplete="address-level2"></div></div><div class="field"><label for="care-day">When do you want to go?</label><div class="input-icon">${icon('calendar')}<select id="care-day" name="day"><option ${state.request.day==='Today'?'selected':''}>Today</option><option ${state.request.day==='Tomorrow'?'selected':''}>Tomorrow</option></select></div></div></div>
    <label class="field-label">What matters most?</label><div class="priority-options">${[['balanced','sparkle','Balanced visit'],['wait','clock','Less waiting'],['cost','money','Lower cost']].map(([value,ic,label])=>`<label><input type="radio" name="priority" value="${value}" ${state.request.priority===value?'checked':''}><span>${icon(ic)}${label}</span></label>`).join('')}</div>
    <button class="button primary full" type="submit">Find my best visit ${icon('arrow-right')}</button><div class="emergency-note">${icon('shield')}<p>Medical emergency? Seek local emergency care. CareFlow is for visit planning.</p></div></form></section>
    <div class="home-plan-column">${planPreview(best())}<div class="quiet-note">${icon('shield')}<span>A plan you can understand.<br><strong>Every recommendation has a reason.</strong></span></div></div></div>
    <section class="how-it-works"><div class="section-caption">THE WHOLE VISIT, CONSIDERED</div><div class="benefits-grid">${[['stethoscope','Care that fits','Doctor and service availability, considered together.'],['clock','Your time matters','Travel, waiting and treatment in one clear timeline.'],['refresh','Room for change','Explore a new plan when availability changes.']].map(([ic,title,text])=>`<article><span class="benefit-icon">${icon(ic)}</span><div><h3>${title}</h3><p>${text}</p></div></article>`).join('')}</div></section>`;
  }
  function understanding(){
    const steps=[['Understanding your request','Consultation, required services and preferred day'],['Checking suitable facilities','Matching your needs with demo service availability'],['Comparing the complete visit','Considering travel, waiting time and estimated cost'],['Finding your best visit plan','Bringing the pieces together']];
    return `${heading('A CLEARER PICTURE','Connecting your care.','We’re comparing complete visits using the demo dataset.')}<section class="card understanding-card" aria-busy="true"><div class="analysis-orbit">${icon('sparkle')}</div><h2>Here’s what we understood</h2><div class="understood-tags">${tags(state.request)}<span class="service-tag">${icon('calendar')}${h(state.request.day)}</span></div><p class="muted">${h(state.request.text)}</p><div class="analysis-steps">${steps.map(([title,detail],i)=>`<div class="analysis-step ${state.analysisStep>i?'done':state.analysisStep===i?'active':''}"><span class="analysis-step-icon">${state.analysisStep>i?icon('check'):state.analysisStep===i?'<span class="spinner"></span>':String(i+1).padStart(2,'0')}</span><div><strong>${title}</strong><p>${detail}</p></div>${state.analysisStep>i?'<span class="small-state">Checked</span>':''}</div>`).join('')}</div><p class="analysis-footnote">Rule-based request matching · no external AI service connected</p><button class="text-button" data-action="cancel-analysis">Cancel and edit request</button></section>`;
  }
  function whyPanel(f){return `<section class="card why-card"><div class="section-heading"><span class="round-icon pale">${icon('sparkle')}</span><div><h2>Why this plan?</h2><p>A little context behind your recommendation.</p></div></div><div class="why-list"><div>${icon('check')}<p><strong>All the care you requested</strong><span>${h(state.request.services.map(s=>M.serviceLabels[s]).join(' + '))} are available in this demo facility.</span></p></div><div>${icon('clock')}<p><strong>Your time, considered together</strong><span>${f.travel} minutes travelling + ${f.wait} minutes waiting. ${M.duration(f.total)} estimated total visit, including care.</span></p></div><div>${icon('money')}<p><strong>Costs you can compare</strong><span>${money(f.cost)} in sample service fees. Travel charges are not included.</span></p></div></div><div class="why-bottom"><span class="status-dot"></span>Based on ${state.request.priority==='cost'?'your lower-cost preference':state.request.priority==='wait'?'your shorter-wait preference':'a balance of time, cost and simulated completion'}.</div></section>`;}
  function results(){const f=best();return `${heading('YOUR OPTIONS, MADE CLEAR','A good day starts with a plan.','Here’s the complete visit that fits your request best.',`<button class="button secondary" data-action="edit-request">${icon('refresh')} New request</button>`)}${requestSummary()}<div class="results-grid"><div>${planPreview(f,'result')}</div><div>${f?whyPanel(f):''}<div class="card decision-note"><span class="round-icon pale">${icon('route')}</span><div><h3>The nearest isn’t always the quickest.</h3><p>Compare the whole visit: required services, travel, waiting and cost.</p><a class="text-button" href="#compare">Compare all ${state.facilities.length} facilities ${icon('arrow-right')}</a></div></div></div></div>${footerNote()}`;}
  function facilityCard(f,index){const isBest=f.id===best()?.id;return `<article class="card facility-card ${isBest?'recommended':''} ${!f.eligible?'unavailable':''}">${isBest?`<div class="recommendation-strip">${icon('sparkle')} RECOMMENDED FOR YOUR VISIT <span>Best overall fit</span></div>`:''}<div class="facility-card-body"><div class="facility-card-top"><span class="hospital-symbol">${icon('buildings')}<b>${f.id}</b></span><div><h2>${h(f.name)}</h2><p>${h(f.area)} <span>·</span> ${h(f.tag)}</p></div><span class="facility-rank">0${index+1}</span></div><div class="facility-status-line">${statusBadge(f)}<span class="muted small">Sample status</span></div><div class="comparison-metrics"><div>${icon('car')}<span>Travel</span><strong>${f.travel} min</strong></div><div>${icon('clock')}<span>Waiting</span><strong>${f.wait} min</strong></div><div>${icon('money')}<span>Cost</span><strong>${money(f.cost)}</strong></div><div>${icon('route')}<span>Total visit</span><strong>${f.eligible?M.duration(f.total):'Incomplete'}</strong></div></div><div class="facility-services">${state.request.services.map(s=>`<span class="${f.services[s]?'available-service':'missing-service'}">${icon(f.services[s]?'check':'close')}${h(M.serviceLabels[s])}</span>`).join('')}</div><div class="facility-card-footer"><div><strong>${f.completionEstimate?f.completionEstimate+'%':'—'}</strong><span>Simulated completion estimate</span></div><button class="button ${isBest?'primary':'secondary'}" data-action="choose-plan" data-id="${f.id}" ${!f.eligible?'disabled':''}>${f.eligible?'Choose this plan':'Unavailable'} ${icon('arrow-right')}</button></div></div></article>`;}
  function mapPanel(selected,visibleFacilities){const routeCoords={A:'M 35 79 Q 18 61 25 37',B:'M35 79 Q55 62 44 24',C:'M35 79 Q49 75 52 64 T69 47',D:'M35 79 Q60 83 65 53 T79 20'};return `<section class="card map-card"><div class="map-heading"><div><h2>Your options, nearby</h2><p>Illustrative map · fictional locations</p></div><span class="badge neutral">${h(state.profile.location)}</span></div><div class="map-canvas" role="group" aria-label="Illustrative facility map"><div class="map-world" style="transform:scale(${state.mapZoom})"><svg viewBox="0 0 100 100" preserveAspectRatio="none" class="map-art" aria-hidden="true"><defs><pattern id="blocks" width="16" height="16" patternUnits="userSpaceOnUse"><rect x="1" y="1" width="13" height="13" rx="2.5" fill="#e8ede8"/><rect x="3" y="3" width="9" height="8" rx="1.5" fill="#e1e8e2"/></pattern></defs><rect width="100" height="100" fill="#f7f8f2"/><rect width="100" height="100" fill="url(#blocks)"/><path d="M86 -5 Q57 12 87 37 T84 77 Q72 90 77 105" stroke="#badde3" stroke-width="9" fill="none"/><path d="M0 37h100M32 0v100M0 72h100M65 0v100M0 9 100 89" fill="none" stroke="#fafbf7" stroke-width="3"/><path d="M0 37h100M32 0v100M0 72h100M65 0v100" fill="none" stroke="#d0d9cf" stroke-width=".25"/><path d="M3 53 Q20 45 28 58v9H3zM45 4h15v18H45zM45 86h20v13H45z" fill="#d0e3c6"/><path class="map-route" d="${routeCoords[selected.id]}" fill="none" stroke="#0d8c80" stroke-width="1.1" stroke-dasharray="2 1"/><circle cx="35" cy="79" r="2" fill="#254558" stroke="white" stroke-width="1"/></svg><span class="map-place-label place-one">CENTRAL DISTRICT</span><span class="map-place-label place-two">RIVERSIDE PARK</span><span class="map-home">Your starting point</span>${visibleFacilities.map(f=>`<button class="map-marker ${f.id===selected.id?'active':''} ${!f.eligible?'muted-marker':''}" style="left:${f.x}%;top:${f.y}%" data-action="map-select" data-id="${f.id}" aria-label="Select ${h(f.name)}" aria-pressed="${f.id===selected.id}">${icon('buildings')}<b>${f.id}</b></button>`).join('')}</div><div class="map-zoom"><button data-action="map-zoom-in" aria-label="Zoom in" ${state.mapZoom>=1.6?'disabled':''}>+</button><button data-action="map-zoom-out" aria-label="Zoom out" ${state.mapZoom<=1?'disabled':''}>−</button></div><span class="map-scale">SCHEMATIC · NOT FOR NAVIGATION</span></div><div class="map-bottom-sheet"><div class="sheet-handle"></div><div class="sheet-title"><span class="round-icon pale">${icon('buildings')}</span><div><h3>${h(selected.name)}</h3><p>${selected.travel} min travel · ${selected.wait} min expected wait</p></div>${selected.eligible?`<span class="mini-score">${selected.completion}%<small>demo estimate</small></span>`:''}</div><div class="sheet-bottom">${statusBadge(selected)}<button class="button primary" data-action="choose-plan" data-id="${selected.id}" ${!selected.eligible?'disabled':''}>Choose plan ${icon('arrow-right')}</button></div></div></section>`;}
  function compare(){let list=ranked();if(state.filter==='complete')list=list.filter(f=>f.eligible);if(state.sort==='wait')list.sort((a,b)=>Number(b.eligible)-Number(a.eligible)||a.wait-b.wait);if(state.sort==='cost')list.sort((a,b)=>Number(b.eligible)-Number(a.eligible)||a.cost-b.cost);if(state.sort==='travel')list.sort((a,b)=>Number(b.eligible)-Number(a.eligible)||a.travel-b.travel);const selected=list.find(f=>f.id===state.mapId)||list[0];return `${heading('MAKE AN INFORMED CHOICE','Good care. Better choices.','See how each facility fits your whole visit, not just the journey there.')}${requestSummary()}<div class="comparison-toolbar"><div class="filter-tabs" role="group" aria-label="Filter facilities"><button class="${state.filter==='all'?'active':''}" data-action="filter" data-filter="all">All facilities <span>${state.facilities.length}</span></button><button class="${state.filter==='complete'?'active':''}" data-action="filter" data-filter="complete">Complete visits <span>${ranked().filter(f=>f.eligible).length}</span></button></div><div class="comparison-controls"><label class="sort-label">Sort by <select id="facility-sort">${[['recommended','Recommended'],['wait','Waiting time'],['cost','Lowest cost'],['travel','Travel time']].map(([v,label])=>`<option value="${v}" ${state.sort===v?'selected':''}>${label}</option>`).join('')}</select></label><div class="view-toggle" role="group" aria-label="View style"><button class="${state.viewMode==='list'?'active':''}" data-action="view-list" aria-pressed="${state.viewMode==='list'}">${icon('list')}<span>List</span></button><button class="${state.viewMode==='map'?'active':''}" data-action="view-map" aria-pressed="${state.viewMode==='map'}">${icon('map')}<span>Map</span></button></div></div></div>${state.viewMode==='map'&&selected?mapPanel(selected,list):`<div class="facility-grid">${list.map(facilityCard).join('')||'<div class="card empty-card"><h2>No complete visits available</h2><p>Restore availability using the demo controls.</p></div>'}</div>`}${footerNote()}`;}
  function plan(){
    if(!state.plan)return `${heading('YOUR VISIT, ALL TOGETHER','A clearer path awaits.','Create a visit plan to see every step from leaving home to completing care.')}<section class="card empty-card"><span class="empty-illustration">${icon('route')}</span><h2>Your next visit starts here</h2><p>Tell us what care you need and we’ll put your options in order.</p><a class="button primary" href="#home">Plan a visit ${icon('arrow-right')}</a><button class="text-button" data-action="use-example">Explore the orthopedic + X-ray example</button></section>${recentHistory()}`;
    const request=state.plan.request;const f=M.evaluate(facilityById(state.plan.facilityId),request);const timeline=M.timeline(f,request);const finished=state.plan.step>=timeline.length-1;const disrupted=!finished&&!f.eligible;const progress=Math.max(0,Math.min(100,((state.plan.step+1)/timeline.length)*100));
    return `${heading('YOUR DAY, THOUGHTFULLY PLANNED',finished?'Your visit is complete.':'Every step, a little clearer.',finished?'You’ve reached the end of this demo journey.':'Your complete visit, from leaving home to finishing care.',`<div class="heading-actions"><button class="button secondary" data-action="save-plan">${icon('save')} Save on this device</button><button class="icon-button bordered" data-action="print" aria-label="Print visit plan">${icon('print')}</button></div>`)}
    ${disrupted?`<div class="disruption-banner" role="alert"><span class="round-icon amber">${icon('alert')}</span><div><strong>Your plan needs a fresh look.</strong><p>A required service changed at ${h(f.short)}. Review another complete visit before continuing.</p></div><button class="button amber-button" data-action="review-replan">Review new plan ${icon('arrow-right')}</button></div>`:''}
    <div class="visit-grid"><section class="card timeline-card"><div class="section-heading"><div><p class="eyebrow">${h(request.day.toUpperCase())} · DEMO SCHEDULE</p><h2>Your visit timeline</h2></div><span class="badge ${finished?'positive':disrupted?'warning':'neutral'}">${finished?'Complete':disrupted?'Needs review':state.plan.step<0?'Ready when you are':'Journey in progress'}</span></div><div class="timeline-summary"><div>${icon('clock')}<span>Estimated total<strong>${M.duration(f.total)}</strong></span></div><div>${icon('clock')}<span>Expected waiting<strong>${f.wait} min</strong></span></div><div>${icon('check')}<span>Estimated finish<strong>${M.time(timeline[timeline.length-1].time)}</strong></span></div></div><ol class="journey-timeline">${timeline.map((event,i)=>`<li class="${i<=state.plan.step?'complete':''} ${i===state.plan.step+1&&!finished?'next':''}"><time>${M.time(event.time)}</time><span class="timeline-node">${icon(i<=state.plan.step?'check':event.icon)}</span><div><h3>${event.label}${i===state.plan.step+1&&!finished?'<span>UP NEXT</span>':''}</h3><p>${h(event.detail)}</p>${event.key==='arrive'?`<small>${h(f.name)}</small>`:''}</div></li>`).join('')}</ol><div class="journey-progress"><div><span>${finished?'All steps completed':`${Math.max(0,state.plan.step+1)} of ${timeline.length} steps completed`}</span><strong>${Math.round(progress)}%</strong></div><div class="progress-track"><span style="width:${progress}%"></span></div></div><div class="timeline-actions"><span>${icon('info')} Actions advance this demo only.</span>${finished?'<a class="button primary" href="#home">Plan another visit</a>':`<button class="button primary" data-action="advance-plan" ${disrupted?'disabled':''}>${state.plan.step<0?'Start demo journey':state.plan.step+1===timeline.length-1?'Complete demo visit':'Mark “'+h(timeline[state.plan.step+1].label)+'” done'} ${icon('arrow-right')}</button>`}</div></section><div class="visit-sidebar"><section class="card visit-destination"><div class="destination-art"><span class="destination-building">${icon('buildings')}</span><span class="destination-pill">FACILITY ${h(f.id)}</span></div><div class="destination-body"><p class="eyebrow">YOUR DESTINATION</p><h2>${h(f.name)}</h2><p>${h(f.area)} · ${h(state.profile.location)} (demo)</p>${statusBadge(f)}<div class="destination-stats"><div><span>Suggested arrival</span><strong>1:20 PM</strong></div><div><span>Estimated service cost</span><strong>${money(f.cost)}</strong></div></div><div class="plan-services">${tags(request)}</div><a class="button secondary full" href="#compare" data-action="open-plan-map">${icon('map')} View illustrative map</a></div></section><div class="calm-card">${icon('refresh')}<h3>Plans can change.<br>We’ll help you adapt.</h3><p>Try a service disruption to see a new visit option.</p><button class="text-button" data-action="simulate-disruption" ${disrupted||finished?'disabled':''}>Simulate a change ${icon('arrow-right')}</button></div></div></div>${footerNote()}`;
  }
  function recentHistory(){if(!state.history.length)return '';return `<section class="recent-section"><h2>Recent completed journeys</h2>${state.history.slice(-3).reverse().map(item=>`<div class="history-row"><span class="round-icon pale">${icon('check')}</span><div><strong>${h(item.facility)}</strong><span>${h(item.services)} · Completed in the demo</span></div><span class="badge positive">Complete</span></div>`).join('')}</section>`;}
  function updates(){return `${heading('STAY IN THE LOOP','A little clarity, as things change.','Service changes and visit updates, together in one place.',`<button class="button secondary" data-action="mark-read">${icon('check')} Mark all as read</button>`)}<section class="card updates-card"><div class="section-heading"><h2>Your updates</h2><span class="badge neutral">${state.updates.length} ${state.updates.length===1?'update':'updates'}</span></div>${state.updates.slice().reverse().map(u=>`<article class="update-row ${u.read?'':'unread'}"><span class="round-icon ${u.type==='warning'?'amber':'pale'}">${icon(u.type==='warning'?'alert':u.type==='success'?'check':'sparkle')}</span><div><div class="update-title"><h3>${h(u.title)}</h3>${!u.read?'<i aria-label="Unread"></i>':''}</div><p>${h(u.text)}</p><time>${h(u.time)}</time>${u.type==='warning'&&state.plan?.status==='needs-review'?'<button class="text-button" data-action="review-replan">Review your new option '+icon('arrow-right')+'</button>':''}</div><button class="icon-button" data-action="dismiss-update" data-id="${u.id}" aria-label="Dismiss ${h(u.title)}">${icon('close')}</button></article>`).join('')||'<div class="empty-card"><h3>You’re all caught up</h3><p>New demo changes will appear here.</p></div>'}</section>`;}
  function hospital(){const f=facilityById(state.hospitalId);const departmentData=[['Orthopedics',f.queue,20],['General medicine',6,14],['Diagnostics',f.services.xray?4:0,10],['Pharmacy',3,8]];return `${heading('CARE FROM THE OTHER SIDE','A clearer view of patient flow.','A lightweight hospital workspace with simulated operational data.',`<label class="hospital-selector">Facility<select id="hospital-select">${state.facilities.map(v=>`<option value="${v.id}" ${f.id===v.id?'selected':''}>${h(v.short)}</option>`).join('')}</select></label>`)}<div class="dashboard-stats">${[['users','Expected today',f.patients,'Sample patient arrivals'],['clock','Currently waiting',f.queue,'Across demo departments'],['route','Estimated queue wait',f.wait+' min','Editable demo signal'],['chart','Peak period','12–2 PM','Illustrative daily pattern']].map(([ic,label,value,detail])=>`<article class="card dashboard-stat"><span class="round-icon pale">${icon(ic)}</span><p>${label}</p><strong>${value}</strong><span>${detail}</span></article>`).join('')}</div><div class="hospital-grid"><section class="card flow-card"><div class="section-heading"><div><h2>Department overview</h2><p>Current load across your facility.</p></div><span class="badge neutral">Simulated</span></div><div class="department-bars">${departmentData.map(([label,n,max])=>`<div><div><span>${label}</span><strong>${n}<small> / ${max} capacity</small></strong></div><div class="department-track"><span style="width:${n/max*100}%"></span></div></div>`).join('')}</div><div class="chart-key"><span class="status-dot"></span>Illustrative capacity, not a live operational measure</div><div class="arrival-chart"><div class="chart-heading"><h3>Expected arrivals</h3><span>Demo day</span></div><div class="bar-chart" role="img" aria-label="Sample hourly arrivals: 9 AM 8, 10 AM 12, 11 AM 16, noon 24, 1 PM 28, 2 PM 19, 3 PM 13, 4 PM 7">${[8,12,16,24,28,19,13,7].map((n,i)=>`<div><span class="${i===4?'highlight':''}" style="height:${n/28*100}%"><b>${n}</b></span><small>${['9 AM','10 AM','11 AM','12 PM','1 PM','2 PM','3 PM','4 PM'][i]}</small></div>`).join('')}</div></div></section><section class="card availability-card"><div class="section-heading"><span class="round-icon pale">${icon('sliders')}</span><div><h2>Availability controls</h2><p>Change a signal to test re-planning.</p></div></div><form id="availability-form"><div class="switch-row"><div><strong>Consulting doctor</strong><p>${f.doctor?'Available for visits':'Currently unavailable'}</p></div><label class="switch"><input type="checkbox" name="doctor" ${f.doctor?'checked':''} aria-label="Doctor available"><span></span></label></div><div class="switch-row"><div><strong>X-ray service</strong><p>${f.services.xray?'Accepting requests':'Currently unavailable'}</p></div><label class="switch"><input type="checkbox" name="xray" ${f.services.xray?'checked':''} aria-label="X-ray service available"><span></span></label></div><div class="switch-row"><div><strong>Lab tests</strong><p>${f.services.lab?'Accepting requests':'Currently unavailable'}</p></div><label class="switch"><input type="checkbox" name="lab" ${f.services.lab?'checked':''} aria-label="Lab tests available"><span></span></label></div><div class="wait-control"><label for="queue-wait">Expected waiting time <output id="wait-output">${f.wait} min</output></label><input id="queue-wait" name="wait" type="range" min="5" max="120" step="5" value="${f.wait}"><div><span>5 minutes</span><span>120 minutes</span></div></div><button class="button primary full" type="submit">Apply demo update ${icon('refresh')}</button><p class="field-help">Updates affect this browser’s demo. No hospital is contacted.</p></form></section></div><section class="card queue-card"><div class="section-heading"><div><h2>Patient queue</h2><p>Fictional patient entries for the interface.</p></div><span class="badge neutral">Demo data</span></div><div class="table-scroll"><table><thead><tr><th>Patient</th><th>Department</th><th>Check-in</th><th>Waiting</th><th>Status</th></tr></thead><tbody>${[['Demo patient 01','Orthopedics','12:05 PM','25 min','Waiting'],['Demo patient 02','General medicine','12:12 PM','18 min','Waiting'],['Demo patient 03','Diagnostics','12:20 PM','10 min','In progress'],['Demo patient 04','Orthopedics','12:25 PM','5 min','Scheduled']].map(([p,d,t,w,s])=>`<tr><td><span class="table-avatar">${p.slice(-2)}</span>${p}</td><td>${d}</td><td>${t}</td><td>${w}</td><td><span class="badge ${s==='Waiting'?'warning':s==='In progress'?'positive':'neutral'}">${s}</span></td></tr>`).join('')}</tbody></table></div></section>`;}
  function profile(){return `${heading('MAKE IT WORK FOR YOU','Your visit. Your preferences.','A few simple settings to make planning feel more personal.')}<div class="profile-grid"><section class="card profile-card"><div class="profile-header"><span class="large-avatar">${h((state.profile.name[0]||'G').toUpperCase())}</span><div><h2>${h(state.profile.name)}</h2><p>Local demo profile · no account required</p></div></div><form id="profile-form"><div class="field"><label for="profile-name">Display name</label><input id="profile-name" name="name" value="${h(state.profile.name)}" maxlength="60" required autocomplete="given-name"></div><div class="field"><label for="profile-location">Preferred location</label><input id="profile-location" name="location" value="${h(state.profile.location)}" maxlength="80" required autocomplete="address-level2"><p class="field-help">Changes the location label. The prototype uses the same fictional facility set.</p></div><div class="field"><label for="profile-priority">Default planning preference</label><select id="profile-priority" name="priority">${[['balanced','A balanced visit'],['wait','Less waiting'],['cost','Lower cost']].map(([id,text])=>`<option value="${id}" ${state.profile.priority===id?'selected':''}>${text}</option>`).join('')}</select></div><div class="switch-row"><div><strong>Reduce motion</strong><p>Use fewer interface animations.</p></div><label class="switch"><input type="checkbox" name="reducedMotion" ${state.profile.reducedMotion?'checked':''} aria-label="Reduce motion"><span></span></label></div><button class="button primary" type="submit">Save preferences ${icon('check')}</button></form></section><div><section class="card privacy-card"><span class="round-icon pale">${icon('shield')}</span><h2>Stored on this device</h2><p>Saved preferences and visits stay in your browser. This prototype does not send your information to a server.</p><p>Use sample requests when demonstrating the project on a shared device.</p><button class="button secondary" data-action="clear-data">Clear saved demo data</button></section>${recentHistory()}</div></div>`;}
  const viewNames={home:'Overview',understanding:'Understanding your care',results:'Your best visit',compare:'Compare facilities',plan:'My visit plan',updates:'Updates',hospital:'Hospital dashboard',profile:'Preferences'};
  const viewRenderers={home,understanding,results,compare,plan,updates,hospital,profile};
  function render(){
    $('#main-content').innerHTML=viewRenderers[state.screen]();
    $('#current-page').textContent=viewNames[state.screen];
    $('#header-location').textContent=state.profile.location;
    $('#profile-avatar').textContent=state.profile.name.split(/\s+/).filter(Boolean).slice(0,2).map(part=>part[0].toUpperCase()).join('')||'GP';
    document.title=`CareFlow · ${viewNames[state.screen]}`;
    document.body.classList.toggle('reduce-motion',!!state.profile.reducedMotion);
    document.querySelectorAll('[data-nav]').forEach(el=>{const active=el.dataset.nav===state.screen||(el.dataset.nav==='home'&&['results','understanding'].includes(state.screen));el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});
    document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
    const unread=state.updates.filter(u=>!u.read).length;$('#update-count').textContent=unread;$('#update-count').hidden=!unread;$('#notification-dot').hidden=!unread;
  }
  function go(view){if(location.hash==='#'+view){state.screen=view;render();$('#main-content').focus();}else location.hash=view;}
  function onHash(){let view=location.hash.slice(1);if(!viewRenderers[view])view='home';if(view==='understanding'&&!state.analysisTimer)view='home';if(state.analysisTimer&&view!=='understanding'){clearInterval(state.analysisTimer);state.analysisTimer=null;}state.screen=view;closeMenu();render();window.scrollTo({top:0,behavior:'auto'});$('#main-content').focus({preventScroll:true});}
  function toast(text){const element=document.createElement('div');element.className='toast';element.innerHTML=icon('check')+'<span>'+h(text)+'</span>';$('#toast-region').replaceChildren(element);setTimeout(()=>element.remove(),4000);}
  function openDialog(title,body,actions='',type=''){const dialog=$('#app-dialog');$('#dialog-content').innerHTML=`<div class="dialog-top"><span class="round-icon ${type==='warning'?'amber':'pale'}">${icon(type==='warning'?'refresh':'sparkle')}</span><button class="icon-button" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button></div><h2 id="dialog-title">${title}</h2>${body}${actions?'<div class="dialog-actions">'+actions+'</div>':''}`;if(!dialog.open)dialog.showModal();}
  function closeDialog(){$('#app-dialog').close();}
  function closeMenu(){$('#sidebar').classList.remove('is-open');$('#mobile-overlay').hidden=true;$('.menu-toggle').setAttribute('aria-expanded','false');}
  function addUpdate(title,text,type='info'){state.updates.push({id:Date.now()+Math.random(),title,text,type,time:'Just now · demo event',read:false});}
  function choosePlan(id,replanned=false){const facility=facilityById(id);if(!facility)return;const f=M.evaluate(facility,state.request);if(!f.eligible){toast('That facility cannot complete this request. Choose another option.');return;}state.plan={facilityId:id,request:M.clone(state.request),step:-1,status:'ready'};state.mapId=id;addUpdate(replanned?'Your visit plan has been updated':'Your visit plan is ready',`${f.name} · suggested arrival 1:20 PM · ${f.wait} min estimated wait. This is a demo plan.`, 'success');closeDialog();go('plan');toast(replanned?'New demo plan selected.':'Your demo visit plan is ready.');}
  function showReplan(){
    if(!state.plan)return;
    const previous=M.evaluate(facilityById(state.plan.facilityId),state.plan.request);const alternatives=M.rank(state.facilities,state.plan.request).filter(f=>f.eligible&&f.id!==previous.id);const next=alternatives[0];
    if(!next){openDialog('No complete alternative is available.',`<p class="dialog-copy">Every sample facility is missing part of this request. Restore availability using the hospital dashboard or edit the request.</p>`,`<button class="button secondary" data-action="close-dialog">Keep current plan</button><button class="button primary" data-action="go-hospital">Open hospital dashboard</button>`,'warning');return;}
    const unavailable=previous.missing.includes('doctor')?'The consulting doctor':previous.missing.includes('specialty')?'The requested specialty':previous.missing.map(s=>M.serviceLabels[s]||s).join(' + ');
    openDialog('A change in plans. A clear next step.',`<p class="dialog-copy">${h(unavailable||'A service')} is unavailable at <strong>${h(previous.name)}</strong> in this scenario. Here’s another facility that can complete your requested visit.</p><div class="replan-comparison"><div class="old-plan"><small>PREVIOUS PLAN</small><h3>${h(previous.name)}</h3><span class="badge warning">Needs review</span></div><div class="new-plan"><small>NEW RECOMMENDATION</small><h3>${h(next.name)}</h3><span class="badge positive">All services available</span><div class="replan-metrics"><span><strong>${next.travel} min</strong>Travel</span><span><strong>${next.wait} min</strong>Waiting</span><span><strong>${next.completion}%</strong>Demo estimate</span></div><p>Suggested arrival <strong>1:20 PM</strong> · ${money(next.cost)} estimated fees</p></div></div><p class="field-help">Accepting restarts the demo journey at the new facility. No booking is changed or created.</p>`,`<button class="button secondary" data-action="close-dialog">Review later</button><button class="button primary" data-action="accept-replan" data-id="${next.id}">Use updated plan ${icon('arrow-right')}</button>`,'warning');
  }
  function afterAvailabilityChange(id,description){
    addUpdate('Facility availability changed',description,'warning');
    if(state.plan?.facilityId===id&&state.plan.status!=='complete'){const evalPlan=M.evaluate(facilityById(id),state.plan.request);state.plan.status=!evalPlan.eligible?'needs-review':state.plan.step<0?'ready':'in-progress';}
    render();
    if(state.plan?.status==='needs-review')showReplan();else toast('Demo availability updated. Recommendations have been recalculated.');
  }
  function simulateDisruption(){
    if(state.plan?.status==='complete'){toast('This visit is complete. Load a new example journey to try a disruption.');return;}
    if(!state.plan){const f=best();if(!f){toast('Reset the demo first to create a complete visit.');return;}choosePlan(f.id);}
    const f=facilityById(state.plan.facilityId);const target=state.plan.request.services.includes('xray')?'xray':state.plan.request.services.find(s=>s==='lab'||s==='pharmacy');
    if(target)f.services[target]=false;else f.doctor=false;
    afterAvailabilityChange(f.id,`${target?M.serviceLabels[target]:'Consulting doctor'} is now unavailable at ${f.name}. This change was simulated using the demo controls.`);
  }
  function resetDemo(){if(state.analysisTimer)clearInterval(state.analysisTimer);state.analysisTimer=null;state.facilities=M.facilities();state.request=defaultRequest();state.plan=null;state.updates=initialUpdates();state.history=[];state.mapId='C';state.mapZoom=1;state.filter='all';state.sort='recommended';persist();closeDialog();go('home');toast('Demo restored to its starting scenario.');}
  function help(){openDialog('A clearer path to care.',`<div class="help-steps"><div><b>01</b><p><strong>Tell us what you need</strong>Choose a consultation, test or other service.</p></div><div><b>02</b><p><strong>Compare complete visits</strong>Check availability, travel, waiting and sample costs.</p></div><div><b>03</b><p><strong>Follow your plan</strong>Explore a timeline and a service-change scenario.</p></div></div><div class="dialog-note">This is a frontend prototype. Request matching is rule-based, the map is illustrative, and hospital data is simulated. It does not diagnose, reserve care or connect to hospital systems.</div>`,`<button class="button primary" data-action="close-dialog">Got it ${icon('check')}</button>`);}
  function controls(){openDialog('Explore the CareFlow demo.',`<p class="dialog-copy">Run through the full journey with an orthopedic consultation and X-ray, then see what happens when a service becomes unavailable.</p><div class="demo-control-list"><button data-action="load-demo">${icon('route')}<span><strong>Load the example journey</strong><small>Orthopedics + X-ray · Meridian Medical Centre</small></span>${icon('chevron-right')}</button><button data-action="simulate-disruption">${icon('refresh')}<span><strong>Simulate a service disruption</strong><small>Change availability and review a new visit plan</small></span>${icon('chevron-right')}</button><button data-action="go-hospital">${icon('sliders')}<span><strong>Change hospital signals</strong><small>Availability switches and waiting-time control</small></span>${icon('chevron-right')}</button><button data-action="reset-demo">${icon('refresh')}<span><strong>Reset the scenario</strong><small>Clear demo journeys and restore all sample values</small></span>${icon('chevron-right')}</button></div>`);}
  document.addEventListener('click',event=>{
    const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action;
    if(action==='skip-content'){event.preventDefault();$('#main-content').focus();return;}
    if(action==='open-plan-map'){state.viewMode='map';state.mapId=state.plan?.facilityId||'C';state.filter='all';if(state.plan)state.request=M.clone(state.plan.request);return;}
    event.preventDefault();
    switch(action){
      case 'open-menu':$('#sidebar').classList.add('is-open');$('#mobile-overlay').hidden=false;$('.menu-toggle').setAttribute('aria-expanded','true');break;
      case 'close-menu':closeMenu();break;
      case 'close-dialog':closeDialog();break;
      case 'help':help();break;
      case 'demo-controls':controls();break;
      case 'location':openDialog('Where are you starting?',`<form id="location-form"><div class="field"><label for="new-location">Location label</label><input id="new-location" name="location" value="${h(state.profile.location)}" maxlength="80" required><p class="field-help">The demo uses fictional facilities. This changes the label, not actual geographic results.</p></div><button class="button primary full" type="submit">Update location ${icon('check')}</button></form>`);break;
      case 'category':{const category=el.dataset.category;const examples={consultation:'I need an orthopedic consultation and an X-ray today.',test:'I need an X-ray today.',pharmacy:'I need a prescription pickup at a pharmacy today.',followup:'I need an orthopedic follow-up today.',urgent:'I need a general consultation today.'};state.request=M.parseRequest(examples[category],category,state.request.day,state.request.priority);render();if(category==='urgent')openDialog('For urgent needs, seek timely care.',`<p class="dialog-copy">This prototype cannot assess urgency or provide emergency triage. For a medical emergency, seek local emergency care immediately.</p><p class="dialog-copy">You can continue exploring a simulated general consultation for the UI demonstration.</p>`,`<button class="button primary" data-action="close-dialog">Return to the demo</button>`);break;}
      case 'fill-example':state.request=defaultRequest();render();$('#care-need').focus();break;
      case 'edit-request':go('home');break;
      case 'preview-request':state.mapId=best()?.id||'C';go('results');break;
      case 'use-example':state.request=defaultRequest();state.mapId=best()?.id||'C';go('results');break;
      case 'load-demo':state.facilities=M.facilities();state.request=defaultRequest();state.plan=null;closeDialog();go('results');break;
      case 'cancel-analysis':clearInterval(state.analysisTimer);state.analysisTimer=null;go('home');break;
      case 'choose-plan':choosePlan(el.dataset.id);break;
      case 'accept-replan':state.request=M.clone(state.plan.request);choosePlan(el.dataset.id,true);break;
      case 'view-list':state.viewMode='list';render();break;
      case 'view-map':state.viewMode='map';render();break;
      case 'filter':state.filter=el.dataset.filter;render();break;
      case 'map-select':state.mapId=el.dataset.id;render();break;
      case 'map-zoom-in':state.mapZoom=Math.min(1.6,state.mapZoom+.2);render();break;
      case 'map-zoom-out':state.mapZoom=Math.max(1,state.mapZoom-.2);render();break;
      case 'save-plan':toast(persist()?'Your plan was saved on this device.':'This browser cannot save local data. You can still use and print the demo.');break;
      case 'print':window.print();break;
      case 'advance-plan':{if(!state.plan)return;const f=facilityById(state.plan.facilityId);if(!M.evaluate(f,state.plan.request).eligible){showReplan();return;}const events=M.timeline(f,state.plan.request);state.plan.step=Math.min(state.plan.step+1,events.length-1);state.plan.status=state.plan.step===events.length-1?'complete':'in-progress';if(state.plan.status==='complete'){state.history.push({facility:f.name,services:state.plan.request.services.map(s=>M.serviceLabels[s]).join(' + ')});addUpdate('Your demo visit is complete',`You completed the sample journey at ${f.name}.`,'success');}render();toast(state.plan.status==='complete'?'Demo visit complete.':events[state.plan.step].label+' marked complete.');break;}
      case 'simulate-disruption':closeDialog();simulateDisruption();break;
      case 'review-replan':showReplan();break;
      case 'reset-demo':resetDemo();break;
      case 'go-hospital':closeDialog();go('hospital');break;
      case 'mark-read':state.updates.forEach(u=>u.read=true);render();toast('All updates marked as read.');break;
      case 'dismiss-update':state.updates=state.updates.filter(u=>String(u.id)!==el.dataset.id);render();break;
      case 'clear-data':openDialog('Clear saved demo data?',`<p class="dialog-copy">This removes the demo profile, saved visit and completed journeys from this browser.</p>`,`<button class="button secondary" data-action="close-dialog">Keep data</button><button class="button primary" data-action="confirm-clear">Clear local data</button>`);break;
      case 'confirm-clear':try{localStorage.removeItem('careflow-ui-v1');}catch{}state.profile={name:'Guest patient',location:'New Delhi',priority:'balanced',reducedMotion:false};resetDemo();try{localStorage.removeItem('careflow-ui-v1');}catch{}toast('Saved demo data cleared.');break;
    }
  });
  document.addEventListener('submit',event=>{
    if(!['care-form','profile-form','availability-form','location-form'].includes(event.target.id))return;event.preventDefault();const data=new FormData(event.target);
    if(event.target.id==='care-form'){
      const need=String(data.get('need')||'').trim(),locationLabel=String(data.get('location')||'').trim();if(!need||!locationLabel){toast('Add your requested care and starting location.');return;}
      state.request=M.parseRequest(need,state.request.category,data.get('day'),data.get('priority'));state.profile.location=locationLabel;state.analysisStep=0;
      state.analysisTimer=setInterval(()=>{state.analysisStep++;if(state.analysisStep>=4){clearInterval(state.analysisTimer);state.analysisTimer=null;state.mapId=best()?.id||'C';go('results');}else if(state.screen==='understanding')render();},550);go('understanding');
    }
    if(event.target.id==='profile-form'){const name=String(data.get('name')||'').trim(),label=String(data.get('location')||'').trim();if(!name||!label){toast('Please enter a name and location.');return;}state.profile={name,location:label,priority:data.get('priority'),reducedMotion:data.has('reducedMotion')};state.request.priority=state.profile.priority;const saved=persist();render();toast(saved?'Preferences saved on this device.':'Preferences updated for this session. Local storage is unavailable.');}
    if(event.target.id==='location-form'){const label=String(data.get('location')||'').trim();if(!label)return;state.profile.location=label;closeDialog();render();toast('Demo location label updated.');}
    if(event.target.id==='availability-form'){const f=facilityById(state.hospitalId);f.doctor=data.has('doctor');f.services.xray=data.has('xray');f.services.lab=data.has('lab');f.wait=Number(data.get('wait'));afterAvailabilityChange(f.id,`${f.name}: ${f.wait} min estimated wait. Doctor ${f.doctor?'available':'unavailable'}; X-ray ${f.services.xray?'available':'unavailable'}; lab ${f.services.lab?'available':'unavailable'}. Demo signals only.`);}
  });
  document.addEventListener('change',event=>{if(event.target.id==='facility-sort'){state.sort=event.target.value;render();}if(event.target.id==='hospital-select'){state.hospitalId=event.target.value;render();}});
  document.addEventListener('input',event=>{if(event.target.id==='queue-wait')$('#wait-output').textContent=event.target.value+' min';});
  $('#mobile-overlay').addEventListener('click',closeMenu);
  document.addEventListener('keydown',event=>{if(event.key==='Escape')closeMenu();});
  $('#app-dialog').addEventListener('click',event=>{if(event.target===$('#app-dialog')){const rect=event.target.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)closeDialog();}});
  window.addEventListener('hashchange',onHash);
  onHash();
})();
